"""Reproduce the three AI-authored, static Text-to-UI concept outputs (stdlib)."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent
DATA = [('Баланс на каждый день', '1800 ккал · 4 блюда', '900 ₽', '🥗'),
        ('Лёгкий ритм', '1400 ккал · 4 блюда', '850 ₽', '🥑'),
        ('Больше растений', '1700 ккал · 4 блюда', '950 ₽', '🥦')]
COMMON = '''*{box-sizing:border-box}body{margin:0;font:16px Arial,sans-serif;color:#243d2e}h1{font-size:56px;line-height:1.05;margin:20px 0}h2{font-size:28px}h3{font-size:20px}button{min-height:44px;padding:10px 18px;border:0;border-radius:10px;background:#255c42;color:white;font:inherit}header{display:flex;justify-content:space-between;align-items:center;padding:28px 5vw;border-bottom:1px solid #ddd}header strong{font-size:28px}nav{font-size:14px}main{padding:36px 5vw}p{line-height:1.6}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}.filters span{padding:12px;border-radius:24px;background:#e3ebda}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}article{padding:22px;border-radius:18px;background:white;border:1px solid #e1e4da}.art{font-size:88px;text-align:center;padding:30px;background:#e9eedf;border-radius:14px}.price{display:flex;justify-content:space-between;align-items:center}.price b{font-size:24px}aside{padding:24px;background:#edf0e5;border-radius:18px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:32px}.note{font-size:12px;color:#55634f;margin-top:24px}.demo{padding:12px 5vw;background:#f6f6ed;color:#586451;font-size:13px}@media(max-width:760px){h1{font-size:40px}.layout{grid-template-columns:1fr}.cards{grid-template-columns:1fr}header nav{display:none}main{padding:24px 5vw}}'''

def cards():
    return ''.join(f'<article><div class="art">{art}</div><h3>{name}</h3><p>{meta}</p><p>Готовые блюда на весь день. Фиксированный состав.</p><div class="price"><b>{price}<small> / день</small></b><button>Добавить</button></div></article>' for name, meta, price, art in DATA)

def page(title, css, content):
    return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — UI-концепция FoodTech</title><style>{COMMON}{css}</style></head><body><div class="demo">Статическая UI-концепция · кнопки иллюстрируют расположение, заказ не создают</div>{content}</body></html>'''

header = '<header><strong>✳ foodtech.</strong><nav>Меню рационов &nbsp; &nbsp; Личный кабинет</nav><span>Корзина 0</span></header>'
filters = '<div class="filters"><span>Все рационы</span><span>Сбалансированные</span><span>Лёгкие</span><span>Растительные</span></div>'
cart = '<aside><h2>Ваш заказ</h2><p>На один день</p><p>Здесь будет ваш рацион</p><hr><p>Рационы: 0 ₽</p><p>Доставка: —</p><h3>Итого: 0 ₽</h3><button>К оформлению</button><p class="note">Первая доставка не раньше чем через 2 дня</p></aside>'

(ROOT/'concept-01-calm.html').write_text(page('Спокойный выбор',
    'body{background:#fafaf5}.hero{display:grid;grid-template-columns:1.3fr 1fr;align-items:center;gap:30px;padding:25px 0 45px}h1{font-family:Georgia,serif;font-weight:400}h1 em{color:#597342}.hero .art{border-radius:50%;font-size:150px;background:#e9eedf}@media(max-width:760px){.hero{grid-template-columns:1fr}.hero .art{display:none}}',
    header+'<main><section class="hero"><div><p>ГОТОВОЕ ПИТАНИЕ · ВАШ РИТМ</p><h1>Хорошая еда.<br><em>Больше времени</em><br>на себя.</h1><p>Готовый рацион на день или неделю. Без подписки.</p></div><div class="art">🥗</div></section><div class="layout"><section><h2>Найдите свой баланс</h2>'+filters+'<div class="cards">'+cards()+'</div></section>'+cart+'</div></main>'),encoding='utf-8')

(ROOT/'concept-02-warm.html').write_text(page('Тёплая витрина',
    'body{background:#fff3e8;color:#563426}header{border:0}button{background:#b6442a;border-radius:99px}.hero{padding:45px;background:#f6d5ba;border-radius:32px;display:grid;grid-template-columns:1fr .7fr;gap:30px}.hero h1{font-weight:800;letter-spacing:-3px}.hero .art{background:#e8ba91;border-radius:50%;font-size:135px;transform:rotate(-10deg)}.cards{grid-template-columns:repeat(3,1fr)}.art{background:#f6e0c6}.filters span{background:#f6ddc9}.bottom-cart{margin:30px 0 0;background:#563426;color:#fff;padding:24px;border-radius:20px;display:flex;justify-content:space-between;align-items:center}@media(max-width:760px){.hero{padding:24px;grid-template-columns:1fr}.hero .art{display:none}.cards{grid-template-columns:1fr}.bottom-cart{gap:12px}}',
    header+'<main><section class="hero"><div><p>МЕНЬШЕ ГОТОВКИ. БОЛЬШЕ ЖИЗНИ.</p><h1>Твой день.<br>Твоё вкусное меню.</h1><p>Знакомые блюда, готовые наборы.<br>Попробуй один день или выбери неделю.</p><button>Смотреть рационы ↓</button></div><div class="art">🥘</div></section><h2>Сегодня хочется…</h2>'+filters+'<div class="cards">'+cards()+'</div><div class="bottom-cart"><span>Ваш заказ · 0 ₽<br><small>Доставка появится после выбора</small></span><button>К оформлению →</button></div></main>'),encoding='utf-8')

rows = ''.join(f'<article><div class="mini">{art}</div><div><h3>{name}</h3><p>{meta} · Готовое меню</p></div><b>{price} / день</b><button>Добавить +</button></article>' for name,meta,price,art in DATA)
(ROOT/'concept-03-planner.html').write_text(page('Планировщик недели',
    'body{background:#f2f5fb;color:#1d2d4a}.shell{display:grid;grid-template-columns:220px 1fr;min-height:100vh}.sidebar{background:#192c48;color:white;padding:30px 24px}.sidebar p{margin-top:40px}.sidebar b{font-size:26px}h1{font:600 36px Arial;margin:12px 0}.layout{grid-template-columns:minmax(0,1fr) 270px}button{background:#2356b7;border-radius:7px}.filters span{background:#e0e7f4;border-radius:6px}.rows article{display:grid;grid-template-columns:60px minmax(0,1fr) auto auto;align-items:center;gap:16px;margin-bottom:14px;border-radius:8px;padding:18px}.rows h3{font-size:17px;margin:0}.rows p{font-size:12px;color:#5f6a7e;margin-bottom:0}.mini{font-size:44px}aside{background:white;border-radius:8px}header{background:white;padding:22px 5vw}.week{border:1px solid #d0d8e6;background:white;border-radius:8px;padding:18px;margin:24px 0;word-spacing:16px}@media(max-width:1000px){.shell{grid-template-columns:1fr}.sidebar{display:none}.layout{grid-template-columns:1fr}.rows article{grid-template-columns:44px 1fr}.rows b{grid-column:2}}',
    '<div class="shell"><div class="sidebar"><b>foodtech.</b><p>▤ Мой план</p><p>◉ Каталог рационов</p><p>⌁ История заказов</p><p>⚙ Настройки</p></div><div>'+header+'<main><p>ПЛАН ПИТАНИЯ</p><h1>Неделя под контролем</h1><p>Готовые рационы · период 1 день / 7 дней</p><div class="week">ПН ВТ СР ЧТ ПТ СБ ВС</div><div class="layout"><section><h2>Выберите меню</h2>'+filters+'<div class="rows">'+rows+'</div></section>'+cart+'</div><p class="note">Календарь и история показаны как направление развития, вне MVP.</p></main></div></div>'),encoding='utf-8')
print('Created 3 distinct static HTML/CSS concepts')
